import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  Inject,
  Input,
  Optional,
  SimpleChanges,
} from '@angular/core';
import { meIcons } from '@monitel/me-icons';

import { MeIconsRegistry } from './me-icons-registry.service';



@Component({
  selector: 'me-icon',
  template: ` <ng-content></ng-content> `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[style.height]': 'containerSize',
    '[style.width]': 'containerSize'
  },
  styleUrls: ['./me-icons.component.css'],
})
export class MeIconComponent {
  private svgIcon?: SVGElement;
  private svgData?: string;

  @Input() color?: string;
  @Input() name?: meIcons | string;
  @Input({ transform: validateSizeValue }) size: string | number | undefined;
  @Input({ transform: validateSizeValue }) containerSize: string | number | undefined;

  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    if ('name' in changes) {
      this.callInitFn();
    }

    if ('size' in changes) {
      this.setIconSize();
    }
  }

  callInitFn() {
    if (this.svgIcon) {
      this.element.nativeElement.removeChild(this.svgIcon);
    }

    if (this.name) {
      this.svgData = this.meIcon.getIconFromString(this.name, this.color);
    }

    if (this.svgData) {
      this.element.nativeElement.innerHTML = this.svgData;
    }
  }

  setIconSize() {
    const icon = this.element.nativeElement.getElementsByClassName('dx-icon')[0];

    icon.setAttribute('width', this.size);
    icon.setAttribute('height', this.size);
  }

  constructor(
    private element: ElementRef,
    public meIcon: MeIconsRegistry,
    @Optional() @Inject(DOCUMENT) private document: any,
  ) { }
}

function validateSizeValue(value: string | number | undefined) {
  if (Number.isNaN(Number(value))) {
    return value;
  } else {
    return value + 'px';
  }
}